    wrapper.playRider=id=>{const r=data.atlas.riders.find(r=>r.id===id&&r.unlock<=upto),f=r&&places.find(f=>f.id===r.place);if(!f)return false;rider?.remove();rider=el('span','atlas-rider');rider.style.left=f.x+'%';rider.style.top=f.y+'%';rider.setAttribute('aria-hidden','true');rider.innerHTML='<svg viewBox="0 0 64 50" fill="currentColor"><path d="m7 29 5-9 24-2 6-12 9-1 7 9-7 3-7-2-2 13 5 15h-5l-7-13H23l-5 13h-5l4-16-7 4-5 8H1l5-13z"/><circle cx="32" cy="6" r="4"/><path d="m29 11 8 1 3 13-8 1-2-8-9 4-2-4z"/></svg>';plane.append(rider);status.textContent=r.label+' · '+r.quote+' · Temsilî hareket; güzergâh eklenmez.';if(art.quiet())return true;const target=rider,a=motion(target,[{opacity:0,transform:'translate(-28px,-15px) scale(.8)'},{opacity:1,offset:.2},{opacity:1,offset:.8},{opacity:0,transform:'translate(0,-15px) scale(.8)'}],{duration:2600,easing:'ease-in-out'});a?.finished.then(()=>target.remove(),()=>target.remove());return true;};
    function stop(){setLens(false);animations.forEach(a=>a.cancel());animations.clear();rider?.remove();}
    document.addEventListener('book:panel-open',stop,{signal:abort.signal});document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();},{signal:abort.signal});document.addEventListener('book:settings',()=>{animations.forEach(a=>a.cancel());animations.clear();animateWeather();if(art.quiet())setLens(false);},{signal:abort.signal});
    const observer=new ResizeObserver(()=>{if(!box.isConnected)return;wrapper.atlasCamera?.refresh?.();});observer.observe(box);
